const CFG = {"hour":16,"x":-250,"z":-1276,"d":[0,1],"phi":0.5,"pale":13620178,"sky":[["uZen",5004918,0.9],["uMid",9676472,0.9],["uHor",14735816,0.9],["uGlow",15785140,0.8],["uCloudShade",7042692,0.7],["uCloudLit",15131870,0.8]],"fog":0.1,"fogMix":0.85,"rain":0.3,"fk":0.22,"fa":1.6,"sk":1.8,"flash":[0.9,2.3,3.2],"lookY":105,"lookY2":110,"fov":48,"camH":1.8,"debris":1400,"ds":2,"dh":70,"dr":1.2,"bolt":[80,-70],"cam0":[-690,0,-1480],"cam1":[-675,0,-1482]};
g.stage(4); g.game.sky.ask(CFG.hour, 'clear', true);
const T = window.__storm.tornado, S = g.game.sky, U = S.uniforms, SS = window.__storm.sky;
P.tw = { x: CFG.x, y: 5, z: CFG.z };
T.start(CFG.x, CFG.z); T.forced.dx = CFG.d[0]; T.forced.dz = CFG.d[1]; T.forced.phi = CFG.phi;
const gh = (x, z) => { g.teleport(x, z, 0); g.step(20); return g.game.player.y; };
const Y0 = gh(CFG.cam0[0], CFG.cam0[2]), Y1 = gh(CFG.cam1[0], CFG.cam1[2]);
g.teleport(CFG.px ?? CFG.x, CFG.pz ?? CFG.z, 0);
const CC = S.fogFlat.constructor, c1 = new CC(), V3 = g.game.camera.position.constructor;
const pal = (h) => new CC(h);
const PALE = pal(CFG.pale), DK = pal(CFG.dkTop ?? 0x000000);
// A swirl of boards, shingles and brush at the funnel's foot: my own instanced mesh, in world space.
const N = CFG.debris ?? 900, DB = T.debris;
const dm = new DB.constructor(DB.geometry, DB.material.clone(), N);
dm.frustumCulled = false; dm.castShadow = false;
const M4 = DB.matrix.constructor, Q = T.root.quaternion.constructor, E = T.root.rotation.constructor;
const m = new M4(), q = new Q(), e = new E(), vp = new V3(), vs = new V3();
const hs = (i, k) => { const x = Math.sin(i * 127.1 + k * 311.7) * 43758.5453; return x - Math.floor(x); };
const cols = [0x2b2118, 0x3b2d20, 0x4a3a2a, 0x6a5a44, 0xb9ad94, 0xd8d0bd, 0x7a2f22, 0x303a2a];
for (let i = 0; i < N; i++) { const r = hs(i, 1); dm.setColorAt(i, c1.setHex(cols[Math.floor(r * r * cols.length)])); }
dm.material.roughness = 0.95;
T.root.parent.add(dm);
P.mine = dm; dm.onBeforeRender = function () { if (P.mine !== dm) this.visible = false; };
const gy = () => T.root.position.y + 2;
const swirl = (t) => {
  for (let i = 0; i < N; i++) {
    const h0 = hs(i, 11), h1 = hs(i, 12), h2 = hs(i, 13), h3 = hs(i, 14);
    const cyc = 5 + h1 * 9, u = (t / cyc + h0) % 1;
    const hmax = (CFG.dh ?? 55) * (0.25 + h2 * h2 * 1.4);
    const y = Math.pow(u, 0.8) * hmax;
