    const a = h2 * 6.283 + t * (1.3 + 26 / (r + 4)) * (0.8 + h3 * 0.4) + u * 2;
    const sc = (CFG.ds ?? 1) * (0.35 + h0 * h0 * 1.9) * (1 - Math.pow(u, 6));
