const T0 = {};
const grade = () => {
  // Sky: lighter and cooler behind the funnel, with less haze between camera and funnel.
  const L = (n, hex, a) => { const v = U[n] && U[n].value; if (v) v.lerp(c1.setHex(hex), a); };
  for (const [n, hex, a] of CFG.sky) L(n, hex, a);
  S.fog.density *= CFG.fog;
  for (const k of ['horBase', 'horGlow', 'fogFlat']) S[k].lerp(PALE, CFG.fogMix);
  if (CFG.rain != null && S.rainU) S.rainU.uAmount.value *= CFG.rain;
