  const sh = T.shellU || [];
  for (let i = 0; i < sh.length; i++) { sh[i].uCol.value.multiplyScalar(CFG.fk ?? 0.5); if (CFG.fa) sh[i].uAlpha.value = Math.min(1, sh[i].uAlpha.value * CFG.fa); }
