const flashes = CFG.flash || [];
// Lightning: a jagged bolt (thin emissive boxes) from the wall cloud, and a flicker of the whole sky.
const NB = 16, bolt = new DB.constructor(DB.geometry, DB.material.clone(), NB);
bolt.frustumCulled = false; bolt.castShadow = false; bolt.count = 0;
bolt.material.color.setHex(0xffffff); bolt.material.emissive.setHex(0xcfe0ff); bolt.material.emissiveIntensity = 6; bolt.material.toneMapped = false; bolt.material.fog = false;
for (let i = 0; i < NB; i++) bolt.setColorAt(i, c1.setHex(0xffffff));
T.root.parent.add(bolt);
bolt.onBeforeRender = function () { if (P.mine !== dm) this.visible = false; };
const Yax = new V3(0, 1, 0), pa = new V3(), pb = new V3(), dd = new V3();
let boltAt = -9, bseed = 1;
const strike = () => {
  bseed++; const bx = P.tw.x + (CFG.bolt?.[0] ?? -140), bz = P.tw.z + (CFG.bolt?.[1] ?? 40);
  let x = bx + (hs(bseed, 1) - 0.5) * 60, y = 235, z = bz;
  const gx = bx + (hs(bseed, 2) - 0.5) * 30, gzz = bz + (hs(bseed, 3) - 0.5) * 30, g0 = gy();
