    const f = (i + 1) / NB, nx = x + (gx + (hs(bseed, 10 + i) - 0.5) * 26 * (1 - f) - x) * 0.5 + (hs(bseed, 30 + i) - 0.5) * 16, ny = 235 + (g0 - 235) * f, nz = z + (gzz - z) * 0.3 + (hs(bseed, 50 + i) - 0.5) * 10;
    pa.set(x, y, z); pb.set(nx, ny, nz); dd.copy(pb).sub(pa); const len = dd.length(); dd.normalize();
    q.setFromUnitVectors(Yax, dd); vp.copy(pa).add(pb).multiplyScalar(0.5); vs.set(0.9 + 0.6 * (1 - f), len, 0.9 + 0.6 * (1 - f));
