  bolt.instanceMatrix.needsUpdate = true; bolt.count = NB;
};
const flashK = (t) => { let k = 0; for (const f of flashes) { const a = t - f; if (a >= 0) k = Math.max(k, Math.max(0, 1 - a / 0.2) * (0.6 + 0.4 * Math.sin(a * 90) ** 2)); } return k; };

P.each = (dt) => {
  const p = T.pos; if (p && (p.x || p.z)) { P.tw.x = p.x; P.tw.z = p.z; }
  grade(); swirl(P.t);
  for (const f of flashes) if (P.t >= f && P.t < f + dt * 1.5) strike();
  const fk2 = flashK(P.t); bolt.visible = fk2 > 0.25;
  if (fk2 > 0) { for (const n of ['uZen','uMid','uHor','uCloudShade','uCloudLit']) U[n]?.value.lerp(c1.setHex(0xf2f6ff), 0.55 * fk2); S.hemi.intensity += 2.2 * fk2; S.sun.intensity += 1.2 * fk2; for (const k of ['horBase','horGlow','fogFlat']) S[k].lerp(c1.setHex(0xe8eeff), 0.5 * fk2); }
};
// Camera: a fixed dolly in world space that keeps the funnel framed.
const ease = (x) => x * x * (3 - 2 * x);
P.place = (cam, s) => {
  const a = CFG.cam0, b = CFG.cam1, u = ease(s);
  const pos = [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * u); pos[1] = Y0 + (Y1 - Y0) * u + CFG.camH;
